import { modulesForFile, modulesForFiles } from '@/flaky/attribution.js';
import type { AppMap, Evidence, EvidenceRef, Surface } from '@/core/types/site-map.js';
import { readCanonicalSiteMap, readAllJourneys } from '@/site-map/store.js';

import { loadCaptureScripts, type LoadedCaptureScript } from './capture-script.js';
import type { VeMatchedBy, VeSkip } from './types.js';

export interface ResolvedPlanEntry {
  journey_id: string;
  capture_script: string;
  loaded: LoadedCaptureScript;
  matched_by: VeMatchedBy[];
}

export interface VisualEvidencePlan {
  entries: ResolvedPlanEntry[];
  skips: VeSkip[];
}

function toPosix(file: string): string {
  return file.replace(/\\/g, '/');
}

function evidenceList(ref: EvidenceRef | undefined): Evidence[] {
  if (!ref) return [];
  return Array.isArray(ref) ? ref : [ref];
}

function anchorMatches(evidenceFile: string, changedFile: string): boolean {
  const a = toPosix(evidenceFile);
  const b = changedFile;
  if (a === b) return true;
  if (b.startsWith(`${a}/`)) return true;
  if (a.startsWith(`${b}/`)) return true;
  return false;
}

function surfaceMatches(
  surface: Surface,
  changedFiles: string[],
  changeModules: Set<string>,
  projectRoot: string,
): VeMatchedBy[] {
  const anchors = evidenceList(surface.evidence);
  const surfaceModule = surface.module ?? '';
  const out: VeMatchedBy[] = [];
  const seen = new Set<string>();
  for (const file of changedFiles) {
    let matched = false;
    if (anchors.some((anchor) => anchorMatches(anchor.file, file))) {
      matched = true;
    }
    if (!matched && surfaceModule && changeModules.has(surfaceModule)) {
      matched = true;
    }
    if (!matched) continue;
    const fileModule = surfaceModule || modulesForFile(projectRoot, file)[0] || '';
    const key = `${file}�${surface.id}�${fileModule}`;
    if (!seen.has(key)) {
      seen.add(key);
      out.push({ file, surface: surface.id, module: fileModule });
    }
  }
  return out;
}

function journeySurfaces(entry: string, stepSurfaces: string[]): Set<string> {
  return new Set<string>([entry, ...stepSurfaces].filter(Boolean));
}

export function resolveVisualEvidencePlan(
  projectRoot: string,
  changedFiles: string[],
): VisualEvidencePlan {
  const files = changedFiles.map(toPosix);
  const skips: VeSkip[] = [];

  const appMap: AppMap | null = readCanonicalSiteMap(projectRoot);
  const surfaces = appMap?.surfaces ?? [];
  const changeModules = new Set(modulesForFiles(projectRoot, files));

  const surfaceMatchedBy = new Map<string, VeMatchedBy[]>();
  for (const surface of surfaces) {
    const matched = surfaceMatches(surface, files, changeModules, projectRoot);
    if (matched.length > 0) {
      surfaceMatchedBy.set(surface.id, matched);
    }
  }

  const { scripts, errors } = loadCaptureScripts(projectRoot);
  for (const error of errors) {
    skips.push({
      reason: 'capture-script-invalid',
      detail: `${error.file}: ${error.errors.join('; ')}`,
    });
  }
  const scriptByJourney = new Map<string, LoadedCaptureScript>();
  for (const script of scripts) {
    scriptByJourney.set(script.journey.id, script);
  }

  const entries: ResolvedPlanEntry[] = [];
  let anyJourneyMatched = false;

  const journeys = readAllJourneys(projectRoot)
    .filter((journey) => journey.status === 'confirmed')
    .sort((a, b) => a.id.localeCompare(b.id));

  for (const journey of journeys) {
    const referenced = journeySurfaces(
      journey.entry,
      journey.steps.map((step) => step.surface),
    );
    const matchedSurfaces = [...referenced].filter((id) => surfaceMatchedBy.has(id));
    if (matchedSurfaces.length === 0) {
      continue;
    }
    anyJourneyMatched = true;

    const matched_by: VeMatchedBy[] = [];
    const seen = new Set<string>();
    for (const surfaceId of matchedSurfaces) {
      for (const row of surfaceMatchedBy.get(surfaceId) ?? []) {
        const key = `${row.file}�${row.surface}�${row.module}`;
        if (!seen.has(key)) {
          seen.add(key);
          matched_by.push(row);
        }
      }
    }

    const loaded = scriptByJourney.get(journey.id);
    if (!loaded) {
      skips.push({
        reason: 'no-capture-script',
        detail: `journey "${journey.id}" matched the change but has no ${journey.id}.capture.yaml`,
      });
      continue;
    }
    entries.push({
      journey_id: journey.id,
      capture_script: loaded.file,
      loaded,
      matched_by,
    });
  }

  if (!anyJourneyMatched) {
    skips.push({
      reason: 'no-documented-flow',
      detail: 'no confirmed journey references a surface this change touches',
    });
  }

  return { entries, skips };
}
